import type { SidebarsConfig } from '@docusaurus/plugin-content-docs'

// Doc items are checked at build time: a sidebar entry for a page that does not
// exist fails the build instead of rendering a dead link. Doc ids are paths
// under docs/ without the extension (docs/wiki/status.md → 'wiki/status').
//
// Two ways to list the synced corpus pages:
//   - by hand, as below, when the sidebar is curated (labels, order, a subset);
//   - { type: 'autogenerated', dirName: 'wiki' } to list every synced page, so a
//     new wiki page can never be built but missing from the sidebar.
const sidebars: SidebarsConfig = {
  docs: [
    {
      type: 'category',
      label: 'Start here',
      collapsible: false,
      items: [
        // The landing is src/pages/index.mdx, a page rather than a doc. When it
        // is docs/index.mdx with `slug: /` instead, use { type: 'doc', id: 'index' }.
        { type: 'link', label: 'Overview', href: '/' },
        { type: 'doc', id: 'architecture', label: 'Architecture at a glance' },
      ],
    },
    {
      type: 'category',
      label: 'From the corpus',
      collapsible: false,
      items: [
        { type: 'doc', id: 'wiki/architecture', label: 'Architecture' },
        { type: 'doc', id: 'wiki/decisions', label: 'Decisions' },
        { type: 'doc', id: 'wiki/status', label: 'Status' },
        { type: 'doc', id: 'wiki/log', label: 'Change log' },
      ],
    },
    {
      type: 'category',
      label: 'API reference',
      collapsible: false,
      items: [
        { type: 'doc', id: 'reference', label: 'How it is generated' },
        // Generated HTML in static/, not a Docusaurus route: `pathname://` makes
        // it a plain link (new tab, baseUrl still applied) instead of a router
        // navigation that would 404.
        { type: 'link', label: 'Backend (Compodoc) ↗', href: 'pathname:///reference/backend/' },
        { type: 'link', label: 'Core (TypeDoc) ↗', href: 'pathname:///reference/core/' },
      ],
    },
  ],
}

export default sidebars
